from copy import deepcopy
import json

def transform(grid):
    """Transform grid according to the pattern:
    - Find top horizontal line, bottom horizontal line, and single point
    - The vertical line passes through both the top and bottom lines
    - The vertical line color is the point's original value
    - Point becomes 4
    - Vertical line appears at column = point.col + bottom_start.col
    """
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])
    background = grid[0][0]

    # Find horizontal lines (3+ consecutive same cells)
    lines = {'top': None, 'bottom': None}

    for r in range(rows):
        row = grid[r]
        non_bg = [(c, v) for c, v in enumerate(row) if v != background]
        if len(non_bg) >= 3 and all(v == non_bg[0][1] for _, v in non_bg):
            if lines['top'] is None:
                lines['top'] = {'row': r, 'cols': [c for c, _ in non_bg], 'color': non_bg[0][1]}
                break

    for r in range(rows-1, -1, -1):
        row = grid[r]
        non_bg = [(c, v) for c, v in enumerate(row) if v != background]
        if len(non_bg) >= 3 and all(v == non_bg[0][1] for _, v in non_bg):
            if lines['bottom'] is None:
                lines['bottom'] = {'row': r, 'cols': [c for c, v in non_bg], 'color': non_bg[0][1]}
                break

    # Find single point
    all_cells = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v != background]
    by_color = {}
    for r, c, v in all_cells:
        if v not in by_color:
            by_color[v] = []
        by_color[v].append((r, c))

    point = None
    for v, cells in by_color.items():
        if len(cells) == 1:
            point = {'val': v, 'row': cells[0][0], 'col': cells[0][1]}
            break

    if lines['top'] is None or lines['bottom'] is None or point is None:
        return deepcopy(grid)

    output = deepcopy(grid)

    # Step 1: Replace point with 4
    output[point['row']][point['col']] = 4

    # Step 2: Calculate vertical line column = point.col + bottom_start_col
    vertical_col = point['col'] + lines['bottom']['cols'][0]

    # Step 3: Draw vertical line from top row to bottom-1
    for r in range(lines['top']['row'], lines['bottom']['row']):
        output[r][vertical_col] = point['val']

    return output

