def bg_color(grid):
    return max(Counter(cell for row in grid for cell in row), key=Counter(cell for row in grid for cell in row).get)

def transform(grid):
    bg = bg_color(grid)
    rows = len(grid)
    cols = len(grid[0])
    output = copy.deepcopy(grid)

    # Find horizontal segments of color 2
    h2 = []
    for r in range(rows):
        current = None
        start = None
        length = 0
        for c in range(cols):
            if grid[r][c] == 0:
                if current is not None and length >= 3:
                    h2.append((r, start, c-1, current))
                current = None
                start = None
                length = 0
                continue
            if current == grid[r][c]:
                length += 1
            else:
                if current is not None and length >= 3:
                    h2.append((r, start, c-1, current))
                current = grid[r][c]
                start = c
                length = 1
        if current is not None and length >= 3:
            h2.append((r, start, cols-1, current))

    # Find vertical segments of color 1
    v1 = []
    for c in range(cols):
        current = None
        start = None
        length = 0
        for r in range(rows):
            if grid[r][c] == 0:
                if current is not None and length >= 3:
                    v1.append((c, start, r-1, current))
