                    v1.append((c, start, r-1, current))
                current = grid[r][c]
                start = r
                length = 1
        if current is not None and length >= 3:
            v1.append((c, start, rows-1, current))

    print(f"v1={v1}, h2={h2}")

    if len(v1) == 2 and all(s[3] == 1 for s in v1):
        # Demo 1: vertical segments
        left_col = v1[0][0]
        left_min, left_max = v1[0][1], v1[0][2]
        right_col = v1[1][0]
        right_min, right_max = v1[1][1], v1[1][2]

        # Left: odd rows fill with 0s
        for r in range(left_min, left_max + 1):
            if r % 2 == 1:
                output[r] = [output[r][left_col]] + [0] * (cols - 1)

        # Right: interrupted rows get specific cell changes
        # Find interrupted rows - those with a 0 at specific position between segments
        for r in range(right_min, right_max + 1):
            # Check if row has a 0 at col 5 or some column between segments
            if grid[r] != output[r]:
                continue  # Already changed by left segment
            for c in range(left_col + 1, right_col):
                if grid[r][c] == 0:
                    # Interrupted row: change specific cells
                    output[r] = output[r][:5] + [4, 0, 1] + output[r][8:]
                    break

