        if single and multi:
            left_row, left_c0, left_c1, _ = single[0]
            right_c0, right_c1 = multi[0][1], multi[0][2]  # First right segment

            bridge_c0 = left_c1 + 1
            bridge_c1 = right_c0 - 1
            bridge_cols = list(range(bridge_c0, bridge_c1 + 1))

            # Left segment row stays as-is
            # Header row (left_row): first bridge col gets 4
            output[left_row][bridge_c0] = 4

            # Bridge rows: from left_row+1 to first_right_row-1
            first_right_row = multi[0][0]
            for r in range(left_row + 1, first_right_row):
                for c in bridge_cols:
                    output[r][c] = 1

            # Right segment rows: keep only rightmost 2
            for r in [s[0] for s in multi]:
                c0, c1 = next((s[1], s[2]) for s in multi if s[0] == r)
                for c in range(c0, c1 + 1):
                    if c == c1:  # Keep only rightmost
                        output[r][c] = 2
                    else:
                        output[r][c] = bg

