# Let me count segments more carefully without color filtering
# I need to count how many Starting color changes in each direction

def raw_get_segments(grid):
    """Get ALL segments regardless of color or orientation"""
    segs = {'vertical': [], 'horizontal': []}

    # Vertical: for each column, track segments (non-0 runs)
    for c in range(len(grid[0])):
        color_runs = []
        current = None
        start = None
        for r in range(len(grid)):
            val = grid[r][c]
            if val == 0:  # skip
                if current is not None:
                    color_runs.append((current, start, r-1))
                current = None
                start = None
            elif current is None:
                current = val
                start = r
            elif current != val:
                color_runs.append((val, start, r-1))
                current = val
                start = r
        if current is not None:
            color_runs.append((current, start, len(grid)-1))

        # Store unique color runs for this column
        seen = {}
        for color, r1, r2 in color_runs:
            if color not in seen:
                seen[color] = (r1, r2)
            else:
                # Extend if contiguous
                if seen[color][0] - 1 == r1 or seen[color][1] + 1 == r2:
                    seen[color] = (min(seen[color][0], r1), max(seen[color][1], r2))

        for color, (r1, r2) in seen.items():
            segs['vertical'].append((c, r1, r2, color))

    # Horizontal: for each row, track segments (non-0 runs)
    for r in range(len(grid)):
        color_runs = []
        current = None
        start = None
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val == 0:
                if current is not None:
                    color_runs.append((current, start, c-1))
                current = None
                start = None
            elif current is None:
                current = val
                start = c
            elif current != val:
                color_runs.append((val, start, c-1))
                current = val
                start = c
        if current is not None:
            color_runs.append((current, start, len(grid[0])-1))

        seen = {}
        for color, c1, c2 in color_runs:
            if color not in seen:
                seen[color] = (c1, c2)
            else:
                if seen[color][1] + 1 == c1 or seen[color][0] - 1 == c2:
                    seen[color] = (min(seen[color][1], c1), max(seen[color][0], c2))

        for color, (c1, c2) in seen.items():
            segs['horizontal'].append((r, c1, c2, color))

    return segs

