import json
from collections import Counter
import copy

with open('/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/seen-2/play/users/u043/system/state/workspace/programs/task-ee69a46b.json') as f:
    demos = json.load(f)

def bg_color(grid):
    return max(Counter(cell for row in grid for cell in row), key=Counter(cell for row in grid for cell in row).get)

def transform(grid):
    bg = bg_color(grid)
    rows = len(grid)
    cols = len(grid[0])
    output = copy.deepcopy(grid)

    # Find vertical segments of color 1 (Demo 1)
    v1_left = None
    v1_right = None
    for c in range(cols):
        current = None
        start = None
        for r in range(rows):
            val = grid[r][c]
            if val == 0:
                continue
            if current is None:
                current = val
                start = r
            elif current == val:
                continue
            else:
                break

        # Check if this is segment of color 1
        if current == 1 and start is not None:
            segment_len = start
            for r in range(start, rows):
                if grid[r][c] == 0:
                    break
                segment_len += 1

            if c == 0:
                v1_left = (c, start, start + segment_len - 1)
            elif c == cols - 1:
                v1_right = (c, start, start + segment_len - 1)

    # Find horizontal segments (Demo 2 - color 2 in rows)
    # Count segments per row
    h2_rows = {}
    for r in range(rows):
        current = None
        segments = []
        for c in range(cols):
            val = grid[r][c]
            if val == 0:
                continue
            if current is None:
                current = val
                start = c
            elif current == val:
                continue
            else:
                segments.append((val, start, c-1))
                current = val
                start = c

        if current is not None:
            segments.append((val, start, cols-1))

        if 2 in [s[0] for s in segments]:
            h2_rows[r] = segments

    print(f"v1_left={v1_left}, v1_right={v1_right}")
    print(f"h2_rows={h2_rows}")

    if v1_left and v1_right:
        # Demo 1 pattern
        left_c, left_r, left_r2 = v1_left
        right_c, right_r, right_r2 = v1_right

        # Left: odd rows fill with 0s
        for r in range(left_r, left_r2 + 1):
            if r % 2 == 1:
                for c2 in range(1, cols):
                    output[r][c2] = 0

        # Right: interrupted rows (7, 9) get special treatment
        for r in range(right_r, right_r2 + 1):
            if r in [7, 9]:
                # Check if interrupted (has 0 between)
                for c2 in range(left_c + 1, right_c):
                    if grid[r][c2] == 0:
                        output[r][left_c + 2] = 4  # col 5
                        output[r][left_c + 3] = 0  # col 6
                        break

    elif h2_rows and any(2 in [s[0] for s in segments] for r, segments in h2_rows.items()):
        # Demo 2 pattern
        # Find rows with 2 segments
        single_row = None
        multi_rows = []

        for r, segments in h2_rows.items():
            if 2 in [s[0] for s in segments]:
                if len([s for s in segments if s[0] == 2]) == 1:
                    single_row = r
                else:
                    multi_rows.append(r)

        print(f"single_row={single_row}, multi_rows={multi_rows}")

        if single_row is not None and multi_rows:
            # Find segments for single row (left segment)
            left_segment = [s for s in h2_rows[single_row] if s[0] == 2][0]
            left_c0, left_c1 = left_segment[1], left_segment[2]

            # Bridge columns
            bridge_c0 = left_c1 + 1
            bridge_c1 = 28  # rightmost
            bridge_cols = range(bridge_c0, bridge_c1)

            # Header (single_row) gets 4 at first bridge col
            output[single_row][bridge_c0] = 4

            # Bridge rows: from left_row+1 to before first multi_row
            first_multi = min(multi_rows)
            for r in range(single_row + 1, first_multi):
                for c in bridge_cols:
                    output[r][c] = 1

            # Right segment rows: clear all 2s, keep only rightmost
            for r in multi_rows:
                multi_seg = [s for s in h2_rows[r] if s[0] == 2][0]
                c0, c1 = multi_seg[1], multi_seg[2]
                # Clear all except rightmost
                for c2 in range(c0, c1):
                    if c2 != c1:
                        output[r][c2] = bg

    return output

