import json
from collections import Counter
import copy

with open('/home/USER/runs/paper/qwen-hpl-u1-turns/frozen/seen-2/play/users/u043/system/state/workspace/programs/task-ee69a46b.json') as f:
    demos = json.load(f)

def bg_color(grid):
    return max(Counter(cell for row in grid for cell in row), key=Counter(cell for row in grid for cell in row).get)

def find_vertical_segments(grid, color):
    """Find vertical segments of specific color"""
    segs = []
    rows = len(grid)
    cols = len(grid[0])

    for c in range(cols):
        current = None
        for r in range(rows):
            val = grid[r][c]
            if val == 0:
                continue
            if current == None and val == color:
                current = color
                start = r
            elif current == color and val == color:
                continue
            elif current == color and val != color:
                break
            else:
                current = val

        if current == color:
            seg_end = rows - 1
            while seg_end >= start and grid[seg_end][c] == color:
                seg_end -= 1
            segs.append((c, start, seg_end))

    return segs

def transform(grid):
    bg = bg_color(grid)
    rows = len(grid)
    cols = len(grid[0])
    output = copy.deepcopy(grid)

    # Find vertical segments of color 1
    v1 = find_vertical_segments(grid, 1)
    print(f"v1 segments={v1}")

    if len(v1) == 2:
        # Demo 1 pattern: two vertical segments of color 1
        left_col, left_r, left_r2 = v1[0]
        right_col, right_r, right_r2 = v1[1]

        print(f"Left: col={left_col}, rows {left_r}-{left_r2}")
        print(f"Right: col={right_col}, rows {right_r}-{right_r2}")

        # Left segment: odd rows fill with 0s
        for r in range(left_r, left_r2 + 1):
            if r % 2 == 1:
                output[r] = [output[r][left_col]] + [0] * (cols - 1)

        # Right segment: interrupted rows (7, 9) get special treatment
        for r in range(right_r, right_r2 + 1):
            if r in [7, 9]:
                input_row = grid[r]
                output[r] = input_row[:5] + [4, 0, 1] + input_row[8:]

    return output

